begin;
select no_plan();
select has_function('public','ai_agent_chat_api_v1',array['text','text','jsonb'],'service-only Chat gateway exists');
select has_table('dashboard_private','chat_delivery_outbox','completion intent has independent durable store');
select is((
 select count(*) from pg_constraint c
 join (values
  ('ai_agent_claim_credential_fk','dashboard_private.ai_agent_request_claims'::regclass,'dashboard_private.ai_agent_credentials'::regclass),
  ('ai_agent_event_credential_fk','dashboard_private.ai_agent_request_events'::regclass,'dashboard_private.ai_agent_credentials'::regclass),
  ('ai_agent_event_issuer_fk','dashboard_private.ai_agent_request_events'::regclass,'public.profiles'::regclass)
 ) expected(name,relation,referenced) on c.conname=expected.name and c.conrelid=expected.relation and c.confrelid=expected.referenced
 where c.contype='f' and c.convalidated
),3::bigint,'final migration chain validates all three credential and issuer foreign keys');
create function pg_temp.ai_id(n integer) returns uuid language sql immutable as $$select ('ae030000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.ai_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','ai-outbox-'||n||'@test.invalid' from generate_series(1,2)n;
insert into public.profiles(id,role,name) select pg_temp.ai_id(n),case n when 1 then 'admin' else 'staff' end,'synthetic outbox' from generate_series(1,2)n on conflict(id) do update set role=excluded.role;
create temp table ev(k text primary key,v jsonb);
grant all on ev to authenticated,service_role;
insert into ev values('old_counts',jsonb_build_object('events',(select count(*) from dashboard_private.notification_events),'deliveries',(select count(*) from dashboard_private.notification_deliveries)));
select is((select count(*) from dashboard_private.chat_space_configuration where not configured and resource_name is null),7::bigint,'all seven spaces start unconfigured without provider resources');
insert into dashboard_private.ai_agent_credentials(id,created_by,label,token_hash,scopes,expires_at) values(pg_temp.ai_id(3),pg_temp.ai_id(1),'synthetic combined',repeat('e',64),array['ai-agent:requests:read','ai-agent:requests:claim','ai-agent:requests:update','chat:outbox:read','chat:send'],clock_timestamp()+interval '1 day'),(pg_temp.ai_id(4),pg_temp.ai_id(1),'synthetic rotated',repeat('f',64),array['chat:outbox:read','chat:send'],clock_timestamp()+interval '1 day');
insert into dashboard_private.ai_agent_credential_grants(credential_id,queues,actions,expires_at) values(pg_temp.ai_id(3),array['employee_requests'],array['read','claim','renew','progress','question','done'],clock_timestamp()+interval '1 day');
insert into dashboard_private.chat_credential_space_grants(credential_id,space_keys,purposes,bridge_source_id,expires_at) values(pg_temp.ai_id(3),array['space_1'],array['ai_completion','bridge_reply'],pg_temp.ai_id(5),clock_timestamp()+interval '1 day'),(pg_temp.ai_id(4),array['space_1'],array['ai_completion','bridge_reply'],pg_temp.ai_id(5),clock_timestamp()+interval '1 day');
-- Synthetic transport configuration exists only within this rolled-back fixture.
update dashboard_private.chat_space_configuration set configured=true,public_origin='https://dashboard.test.invalid',resource_name='spaces/fixture_space' where space_key='space_1';
insert into dashboard_private.chat_user_space_permissions(user_id,space_keys,configured_by) values(pg_temp.ai_id(2),array['space_1'],pg_temp.ai_id(1));
insert into dashboard_private.ai_agent_requests(id,requester_id,title,body,notify_on_done,notification_space) select pg_temp.ai_id(n),pg_temp.ai_id(2),'Synthetic completion','private body must stay private',true,'space_1' from generate_series(10,15)n;
create function pg_temp.claim_it(n integer) returns jsonb language sql as $$select public.ai_agent_bot_api_v1(repeat('e',64),'claim',jsonb_build_object('id',pg_temp.ai_id(n),'version','1','idempotencyKey',pg_temp.ai_id(100+n),'claimTokenHash',repeat('a',64)))$$;
create function pg_temp.done_it(n integer) returns jsonb language sql as $$select public.ai_agent_bot_api_v1(repeat('e',64),'done',jsonb_build_object('id',pg_temp.ai_id(n),'version','2','idempotencyKey',pg_temp.ai_id(200+n),'claimTokenHash',repeat('a',64),'claimGeneration','1','result','private full result'))->'request'$$;
create function pg_temp.rollback_done() returns text language plpgsql as $$begin perform pg_temp.done_it(10);raise exception 'synthetic rollback';exception when others then return SQLSTATE;end$$;
set local role service_role;
select lives_ok($q$select pg_temp.claim_it(n) from generate_series(10,15)n$q$,'completion fixtures claimed');
select is(pg_temp.rollback_done(),'P0001','synthetic transaction abort observed');
reset role;
select is((select status from dashboard_private.ai_agent_requests where id=pg_temp.ai_id(10)),'processing','rollback restores processing request');
select is((select count(*) from dashboard_private.chat_delivery_outbox),0::bigint,'completion rollback produces zero intents');
select is((select count(*) from dashboard_private.ai_agent_request_events where request_id=pg_temp.ai_id(10) and kind='done'),0::bigint,'completion rollback produces zero done events');
set local role service_role;
select is(pg_temp.done_it(10)->>'status','done','completion transaction commits done');
reset role;
insert into ev select 'completion',dashboard_private.chat_outbox_json_v1(o) from dashboard_private.chat_delivery_outbox o where request_id=pg_temp.ai_id(10);
select is((select count(*) from dashboard_private.chat_delivery_outbox where request_id=pg_temp.ai_id(10)),1::bigint,'done commit creates exactly one fixed completion intent');
select is((select v->'payload'->>'text' from ev where k='completion'),'Synthetic completion'||E' · 완료\nhttps://dashboard.test.invalid/admin/ai-agent/'||pg_temp.ai_id(10)::text,'completion payload contains only title/status/authenticated detail link');
select ok((select v::text not like '%private body%' and v::text not like '%private full result%' from ev where k='completion'),'private body and full result not copied into team notification');
