update dashboard_private.chat_space_configuration set configured=false,resource_name=null where space_key='space_1';
set local role service_role;
select is(pg_temp.done_it(11)->>'status','done','configuration removal cannot undo completion');
reset role;
select is((select reason from dashboard_private.chat_delivery_outbox where request_id=pg_temp.ai_id(11)),'space_unconfigured','completion records unconfigured unsent reason');
update dashboard_private.chat_space_configuration set configured=true,public_origin='https://dashboard.test.invalid',resource_name='spaces/fixture_space' where space_key='space_1';
set local role service_role;
select lives_ok($q$select pg_temp.done_it(12)$q$,'policy-revocation fixture completed');
reset role;
update dashboard_private.chat_user_space_permissions set space_keys='{}' where user_id=pg_temp.ai_id(2);
create function pg_temp.prepare(k text,key_n integer,rev text default '1') returns jsonb language sql as $$select public.ai_agent_chat_api_v1(repeat('e',64),'prepare_attempt',jsonb_build_object('id',(select v->>'id' from ev where ev.k=$1),'revision',rev,'idempotencyKey',pg_temp.ai_id(key_n)))$$;
insert into ev select 'revoked',dashboard_private.chat_outbox_json_v1(o) from dashboard_private.chat_delivery_outbox o where request_id=pg_temp.ai_id(12);
set local role service_role;
insert into ev values('revoked_attempt',pg_temp.prepare('revoked',300));
select is((select v->'outbox'->>'reason' from ev where k='revoked_attempt'),'space_permission_revoked','prepare rechecks current requester space permission');
select is((select v->>'attempt' from ev where k='revoked_attempt'),null,'denied dispatch creates no attempt');
reset role;
select is((select status from dashboard_private.ai_agent_requests where id=pg_temp.ai_id(12)),'done','outbox policy cancellation leaves request done');
update dashboard_private.chat_user_space_permissions set space_keys=array['space_1'] where user_id=pg_temp.ai_id(2);
set local role service_role;
insert into ev values('sending',pg_temp.prepare('completion',301));
select is((select v->'outbox'->>'state' from ev where k='sending'),'sending','durable attempt starts before transport');
select is((select v->'attempt'->>'seq' from ev where k='sending'),'1','attempt event seq precision-safe');
reset role;
select is((select attempt_count from dashboard_private.chat_delivery_outbox where id=(select (v->>'id')::uuid from ev where k='completion')),1::bigint,'prepare increments durable count before any provider result');
select is((select payload_hash from dashboard_private.ai_agent_request_receipts where principal_id=pg_temp.ai_id(3) and operation='prepare_attempt' and idempotency_key=pg_temp.ai_id(301)),encode(sha256(convert_to(jsonb_build_object('id',(select v->>'id' from ev where k='completion'),'revision','1')::text,'UTF8')),'hex'),'actual prepare receipt hashes full JSONB input excluding only idempotencyKey');
select isnt((select payload_hash from dashboard_private.ai_agent_request_receipts where principal_id=pg_temp.ai_id(3) and operation='prepare_attempt' and idempotency_key=pg_temp.ai_id(301)),encode(sha256(convert_to(jsonb_build_object('revision','1')::text,'UTF8')),'hex'),'prepare fingerprint includes outbox identity');
set local role service_role;
select is(pg_temp.prepare('completion',301)->>'attempt',null,'duplicate preparation does not authorize a second dispatch');
select throws_ok($q$select pg_temp.prepare('completion',302,'2')$q$,'55000','ai_agent_conflict','sending intent cannot be dispatched twice');
create function pg_temp.record(k text,key_n integer,outcome text,code text,extra jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_chat_api_v1(repeat('e',64),'record_attempt',jsonb_build_object('id',(select v->'outbox'->>'id' from ev where ev.k=$1),'attemptId',(select v->'attempt'->>'attemptId' from ev where ev.k=$1),'idempotencyKey',pg_temp.ai_id(key_n),'outcome',outcome,'code',code)||extra)$$;
insert into ev values('sent',pg_temp.record('sending',303,'sent','200','{"messageName":"spaces/fixture_space/messages/m1","threadName":"spaces/fixture_space/threads/t1"}'));
select is((select v->'outbox'->>'state' from ev where k='sent'),'sent','provider success resource names bind expected space');
select is(pg_temp.record('sending',303,'sent','200','{"messageName":"spaces/fixture_space/messages/m1","threadName":"spaces/fixture_space/threads/t1"}')->'outbox'->>'state','sent','same attempt result replay uses durable state');
select is(pg_temp.prepare('completion',304,'3')->'outbox'->>'state','sent','sent re-request returns saved state without dispatch');
reset role;
select is((select count(*) from dashboard_private.chat_delivery_attempts where outbox_id=(select (v->>'id')::uuid from ev where k='completion')),2::bigint,'one started and one result despite replays');
select throws_ok($q$update dashboard_private.chat_delivery_attempts set seq=100$q$,'55000','ai_agent_immutable','attempt sequence cannot be changed');
select throws_ok($q$delete from dashboard_private.chat_delivery_attempts$q$,'55000','ai_agent_immutable','attempt journal cannot be deleted');
-- Bridge source/event namespace is independent of credential identity.
create function pg_temp.bridge(token text,event text,key_n integer,extra jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_chat_api_v1(token,'chat_outbox',jsonb_build_object('bridgeSourceId',pg_temp.ai_id(5),'sourceEventId','spaces/fixture_space/messages/'||event,'spaceKey','space_1','threadName','spaces/fixture_space/threads/human_fixture','text','Synthetic reply','idempotencyKey',pg_temp.ai_id(key_n))||extra)->'outbox'$$;
set local role service_role;
insert into ev values('bridge',pg_temp.bridge(repeat('e',64),'event-1',310));
insert into ev values('rotated_origin',public.ai_agent_chat_api_v1(repeat('f',64),'chat_outbox',jsonb_build_object('bridgeSourceId',pg_temp.ai_id(5),'sourceEventId','spaces/fixture_space/messages/event-1','spaceKey','space_1','threadName','spaces/fixture_space/threads/human_fixture','text','Synthetic reply','idempotencyKey',pg_temp.ai_id(311))));
select is((select v->'outbox'->>'id' from ev where k='rotated_origin'),(select v->>'id' from ev where k='bridge'),'credential rotation retains stable bridge event dedupe');
select is((select v->>'created' from ev where k='rotated_origin'),'false','rotated current credential new HTTP key saves dedupe receipt and returns created false');
select pg_temp.bridge(repeat('f',64),'event-1',311);
reset role;
select is((select count(*) from dashboard_private.ai_agent_request_receipts where principal_id=pg_temp.ai_id(4) and operation='chat_outbox' and idempotency_key=pg_temp.ai_id(311)),1::bigint,'new rotated credential key stores exactly one current-credential origin receipt');
set local role service_role;
select throws_ok($q$select pg_temp.bridge(repeat('f',64),'event-1',312,'{"text":"different"}')$q$,'23514','ai_agent_idempotency_conflict','same stable event cannot change payload');
select throws_ok($q$select pg_temp.bridge(repeat('e',64),'event-cross',313,'{"threadName":"spaces/other/threads/human_fixture"}')$q$,'22023','chat_thread_invalid','cross-space thread fails before dispatch');
select throws_ok($q$select pg_temp.bridge(repeat('e',64),'event-large',314,jsonb_build_object('text',repeat('한',11000)))$q$,'22023','chat_payload_too_large','serialized UTF-8 message budget enforced');
select throws_ok($q$select pg_temp.bridge(repeat('e',64),'event-unauthorized',315,'{"spaceKey":"space_2"}')$q$,'42501','ai_agent_grant_forbidden','space grant remains decisive');
select throws_ok($q$select pg_temp.bridge(repeat('f',64),'event-1',316,'{"text":" Synthetic reply"}')$q$,'23514','ai_agent_idempotency_conflict','same event leading text whitespace changes identity');
select throws_ok($q$select pg_temp.bridge(repeat('f',64),'event-1',317,'{"text":"Synthetic reply "}')$q$,'23514','ai_agent_idempotency_conflict','same event trailing text whitespace changes identity');
reset role;
update dashboard_private.chat_space_configuration set configured=false,resource_name=null where space_key='space_1';
set local role service_role;
select throws_ok($q$select pg_temp.bridge(repeat('f',64),'event-1',318)$q$,'42501','ai_agent_space_forbidden','current configuration precedes stable source dedupe receipt');
reset role;
update dashboard_private.chat_space_configuration set configured=true,resource_name='spaces/fixture_space' where space_key='space_1';
select is((select count(*) from dashboard_private.chat_delivery_outbox where bridge_source_id=pg_temp.ai_id(5)),1::bigint,'stable bridge dedupe creates only one intent');
update dashboard_private.chat_space_send_budgets set last_dispatch_at=clock_timestamp()-interval '2 seconds';
set local role service_role;
insert into ev values('unknown_sending',pg_temp.prepare('bridge',320));
insert into ev values('unknown',pg_temp.record('unknown_sending',321,'unknown','timeout'));
select is((select v->'outbox'->>'state' from ev where k='unknown'),'delivery_unknown','timeout after dispatch is unknown');
select is(pg_temp.prepare('bridge',320)->'outbox'->>'state','delivery_unknown','original preparation replay returns current unknown');
select is(pg_temp.prepare('bridge',320)->>'attempt',null,'unknown duplicate does not produce dispatch authorization');
select throws_ok($q$select pg_temp.prepare('bridge',322,'3')$q$,'55000','ai_agent_conflict','unknown cannot automatically resend');
select is(jsonb_array_length(public.ai_agent_chat_api_v1(repeat('e',64),'list','{}')->'items'),0,'unknown excluded from ordinary drain');
select throws_ok($q$select public.ai_agent_chat_api_v1(repeat('e',64),'list','{"state":null}')$q$,'22023','ai_agent_invalid','null delivery-state filter rejected by final gateway');
insert into ev values('expired',pg_temp.bridge(repeat('e',64),'event-expired',323));
reset role;
update dashboard_private.chat_space_send_budgets set last_dispatch_at=clock_timestamp()-interval '2 seconds';
set local role service_role;
insert into ev values('expired_sending',pg_temp.prepare('expired',324));
reset role;
