select is(pg_temp.record('expired_sending',326,'sent','200','{"messageName":"spaces/fixture_space/messages/late","threadName":"spaces/fixture_space/threads/human_fixture"}')->'outbox'->>'state','sent','late registered result can append after grant/config removal');
select throws_ok($q$select pg_temp.bridge(repeat('e',64),'event-denied',327)$q$,'42501','ai_agent_grant_forbidden','revoked grant cannot create a new intent');
reset role;
update dashboard_private.chat_credential_space_grants set revoked_at=null where credential_id=pg_temp.ai_id(3);
update dashboard_private.chat_space_configuration set configured=true,public_origin='https://dashboard.test.invalid',resource_name='spaces/fixture_space' where space_key='space_1';
set local role service_role;
insert into ev values('incident',pg_temp.bridge(repeat('e',64),'event-incident',330));
insert into ev values('retry',pg_temp.bridge(repeat('e',64),'event-retry',331));
reset role;
update dashboard_private.chat_space_send_budgets set last_dispatch_at=clock_timestamp()-interval '2 seconds';
set local role service_role;
insert into ev values('incident_sending',pg_temp.prepare('incident',332));
select is(pg_temp.record('incident_sending',333,'sent','200','{"messageName":"spaces/other/messages/m","threadName":"spaces/other/threads/t"}')->'outbox'->>'state','incident','success with wrong resource preserves incident and does not retry');
reset role;
update dashboard_private.chat_space_send_budgets set last_dispatch_at=clock_timestamp()-interval '2 seconds';
set local role service_role;
insert into ev values('retry_sending',pg_temp.prepare('retry',334));
select is(pg_temp.record('retry_sending',335,'rejected_retryable','429')->'outbox'->>'state','retry_wait','explicit nonacceptance 429 has bounded backoff');
reset role;
select ok((select extract(epoch from ready_at-updated_at) >= 1.99 and extract(epoch from ready_at-updated_at) < 3.01 and attempt_count=1 and state='retry_wait' from dashboard_private.chat_delivery_outbox where id=(select (v->>'id')::uuid from ev where k='retry')),'first definite 429 stores two seconds plus subsecond jitter and count one');
set local role service_role;
select is(pg_temp.prepare('retry',334)->>'attempt',null,'same original prepare RPC input replays with null attempt after retry_wait');
select throws_ok($q$select pg_temp.prepare('retry',334,public.ai_agent_chat_api_v1(repeat('e',64),'get',jsonb_build_object('id',(select v->>'id' from ev where k='retry')))->'outbox'->>'revision')$q$,'23514','ai_agent_idempotency_conflict','old key with HTTP latest retry_wait revision conflicts before next dispatch');
reset role;
select ok((select ready_at>clock_timestamp() and attempt_count=1 from dashboard_private.chat_delivery_outbox where id=(select (v->>'id')::uuid from ev where k='retry')),'retry wait stores future DB-ready budget');
-- Retry the same durable bridge intent with fresh attempt keys, never a new
-- event/intent/payload. Fifth definite rejection exhausts the retry policy.
update dashboard_private.ai_agent_credentials set rate_count=0,rate_window=date_trunc('minute',clock_timestamp()) where id=pg_temp.ai_id(3);
create function pg_temp.exhaust_retries() returns jsonb language plpgsql as $$declare prepared jsonb;result jsonb;ai_revision text;begin for n in 2..5 loop
 update dashboard_private.chat_delivery_outbox set ready_at=clock_timestamp()-interval '1 second' where id=(select (value->>'id')::uuid from (select v as value from ev where k='retry')x);
 update dashboard_private.chat_space_send_budgets set last_dispatch_at=clock_timestamp()-interval '2 seconds';
 select revision::text into ai_revision from dashboard_private.chat_delivery_outbox where id=(select (value->>'id')::uuid from (select ev.v as value from ev where k='retry')x);
 prepared:=public.ai_agent_chat_api_v1(repeat('e',64),'prepare_attempt',jsonb_build_object('id',(select ev.v->>'id' from ev where k='retry'),'revision',ai_revision,'idempotencyKey',pg_temp.ai_id(400+n)));
 result:=public.ai_agent_chat_api_v1(repeat('e',64),'record_attempt',jsonb_build_object('id',prepared->'outbox'->>'id','attemptId',prepared->'attempt'->>'attemptId','idempotencyKey',pg_temp.ai_id(410+n),'outcome','rejected_retryable','code','429'));
 if n=2 then insert into ev values('second_retry',result);end if;
 end loop;return result;end$$;
select is(pg_temp.exhaust_retries()->'outbox'->>'state','failed','maximum five attempts exhaust definite retry policy');
select is((select attempt_count from dashboard_private.chat_delivery_outbox where id=(select (v->>'id')::uuid from ev where k='retry')),5::bigint,'retry cap is stored in DB');
select ok((select (v->'outbox'->>'attemptCount')::integer=2 and v->'outbox'->>'state'='retry_wait' and extract(epoch from (v->'outbox'->>'readyAt')::timestamptz-(v->'outbox'->>'updatedAt')::timestamptz)>=3.99 and extract(epoch from (v->'outbox'->>'readyAt')::timestamptz-(v->'outbox'->>'updatedAt')::timestamptz)<5.01 from ev where k='second_retry'),'second definite 429 stores four seconds plus subsecond jitter with count two');
set local role service_role;
insert into ev values('budget',pg_temp.bridge(repeat('e',64),'event-budget',420));
reset role;
update dashboard_private.chat_send_global_budget set minute=date_trunc('minute',clock_timestamp()),count=60;
update dashboard_private.chat_space_send_budgets set last_dispatch_at=clock_timestamp()-interval '2 seconds';
set local role service_role;
select throws_ok($q$select pg_temp.prepare('budget',421)$q$,'54000','chat_rate_limited','global DB dispatch minute budget enforced');
reset role;
update dashboard_private.chat_send_global_budget set count=0;
update dashboard_private.chat_space_send_budgets set last_dispatch_at=clock_timestamp();
set local role service_role;
select throws_ok($q$select pg_temp.prepare('budget',422)$q$,'54000','chat_rate_limited','space dispatch requires at least one second');
reset role;
select is((select count(*) from dashboard_private.chat_delivery_attempts where outbox_id=(select (v->>'id')::uuid from ev where k='budget')),0::bigint,'failed budget reservation has zero attempts');
update dashboard_private.ai_agent_credentials set revoked_at=clock_timestamp() where id=pg_temp.ai_id(3);
set local role service_role;
select throws_ok($q$select pg_temp.record('unknown_sending',423,'sent','200','{"messageName":"spaces/fixture_space/messages/late","threadName":"spaces/fixture_space/threads/human_fixture"}')$q$,'28000','ai_agent_unauthorized','revoked credential cannot append late result');
reset role;
set local role authenticated;
select throws_ok($q$select public.ai_agent_chat_api_v1(repeat('e',64),'list','{}')$q$,'42501',null,'employees cannot execute Chat worker gateway');
reset role;
set local role anon;
select throws_ok($q$select public.ai_agent_chat_api_v1(repeat('e',64),'list','{}')$q$,'42501',null,'anonymous Chat call rejected');
reset role;
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) rr cross join unnest(array['chat_space_configuration','chat_delivery_outbox','chat_delivery_attempts','chat_send_global_budget','chat_space_send_budgets']) tt where has_table_privilege(rr,'dashboard_private.'||tt,'SELECT,INSERT,UPDATE,DELETE')),'all private outbox/config/budget stores deny direct API access');
select is(jsonb_build_object('events',(select count(*) from dashboard_private.notification_events),'deliveries',(select count(*) from dashboard_private.notification_deliveries)),(select v from ev where k='old_counts'),'old notification event/delivery counts stay exactly unchanged');
set local role service_role;
select is(public.ai_agent_chat_api_v1(repeat('f',64),'list','{}')->'nextCursor','null'::jsonb,'Chat list supplies continuation metadata even on terminal page');
select throws_ok($q$select public.ai_agent_chat_api_v1(repeat('f',64),'chat_outbox',jsonb_build_object('bridgeSourceId',pg_temp.ai_id(5),'sourceEventId','arbitrary-event-id','spaceKey','space_1','threadName','spaces/fixture_space/threads/human_fixture','text','synthetic','idempotencyKey',pg_temp.ai_id(450)))$q$,'22023','chat_source_event_invalid','bridge requires canonical original Google message.name');
reset role;

